   $$natuurkunde-vwo-2018-ii-mechanische-doping-vraag2.png$$, $$Leg met behulp van een berekening en met Tabel 19B van Binas of Tabel 5.1.c van Sciencedata uit voor welke soort straling deze camera gevoelig is.$$, array['0bd87cd7-cb59-425e-8bb7-2ef1ab4cb09b']::uuid[]),
  ('89fa120a-30d9-4776-bb84-6100334deed1', '3d84fca9-94e5-4350-9b52-1aa4c0901ac9', 3,
   $$[{"domain": "Lading en veld", "subdomain": "Elektrische systemen"}]$$::jsonb,
   $$["weerstand koperdraad", "soortelijke weerstand", "serieschakeling", "capaciteit batterij", "stroomsterkte berekenen"]$$::jsonb,
