   $$natuurkunde-vwo-2018-ii-mechanische-doping-vraag3.png$$, $$Bereken hoe lang de elektromagneten werken op de batterij als die in het begin volledig opgeladen is. (Verwaarloos de lengte van de draden tussen de elektromagneten.)$$, array['393b6694-39b4-47f5-ae1f-3bba60736d48']::uuid[]),
  ('e57d2557-e9d0-4a6f-9e63-4f575505dc93', '3d84fca9-94e5-4350-9b52-1aa4c0901ac9', 4,
   $$[{"domain": "Lading en veld", "subdomain": "Elektrische en magnetische velden"}]$$::jsonb,
