   $$natuurkunde-vwo-2018-ii-gravitron-vraag7.png$$, $$Bepaal deze afstand met behulp van de figuur op de uitwerkbijlage.$$, array['f11a3d28-0446-442e-bfd9-00575df679a8','e375eeb9-4438-4ef7-97cf-57d78eda8af6']::uuid[]),
