   $$natuurkunde-vwo-2018-ii-wijnfraude-opsporen-vraag20.png$$, $$Toon dat aan met behulp van figuur 1 en een berekening van de dracht.$$, array['15320c21-35a3-43cb-8e83-b364c3628c5e']::uuid[]),
  ('fdcce379-386e-4298-96b0-f9318a8b061f', '10b3a2b1-b92e-4062-9d0a-734f17665c6f', 21,
